import{preloadImages}from"../../libs/utils.js";$=jQuery;let lenis=new Lenis;function introProducts(){$(".intro-products").length<1||new Swiper(".products-swiper",{slidesPerView:5,spaceBetween:24,loop:!0,speed:600,navigation:{nextEl:".products-swiper .arrow-next",prevEl:".products-swiper .arrow-prev"},breakpoints:{0:{slidesPerView:3,spaceBetween:20},768:{slidesPerView:5,spaceBetween:30}}})}function featuredProduct(){$(".product-featured").length<1||new Swiper(".product-featured-swiper",{slidesPerView:1.5,spaceBetween:30,loop:!1,speed:800,pagination:{el:".product-featured-swiper .swiper-pagination"},centeredSlides:!0})}function categoryProducts(){$(".product-category").length<1||new Swiper(".product-category-swiper",{slidesPerView:3.3,spaceBetween:30,loop:!1,speed:800,navigation:{nextEl:".product-category .arrow-next",prevEl:".product-category .arrow-prev"}})}function banner(){$(".banner-swiper").length<1||new Swiper(".banner-swiper",{slidesPerView:1,loop:!1,loop:!0,effect:"fade",speed:800,pagination:{el:".banner-swiper .swiper-pagination"},centeredSlides:!0})}function scrollToTop(){$(".back-to-top").on("click",function(e){e.preventDefault(),lenis.scrollTo(0,{offset:0,duration:.8,easing:e=>e})})}lenis.on("scroll",ScrollTrigger.update),gsap.ticker.add(e=>{lenis.raf(1e3*e)}),gsap.ticker.lagSmoothing(0);let init=()=>{gsap.registerPlugin(ScrollTrigger),banner(),introProducts(),featuredProduct(),categoryProducts(),scrollToTop()},isLinkClicked=(preloadImages("img").then(()=>{init()}),!1);$("a").on("click",function(e){!this.href||this.href.match(/^#/)||this.href.match(/^javascript:/)||(isLinkClicked=!0,console.log("1"))}),$(window).on("beforeunload",function(){isLinkClicked||$(window).scrollTop(0),isLinkClicked=!1});